import Document from "./document.js";
export default class User {
    name;
    email;
    permissions = {};
    language;
    get isLogged() {
        return !!this.name;
    }
    constructor(name, config) {
        this.name = config?.name ?? name;
        this.email = config?.email;
        this.permissions = config?.permissions ?? {};
        this.language = config?.language;
    }
    // TO-DO: Implement view permissions
    canView(_subject) {
        return true;
    }
    canCreate(subject) {
        if (!this.canView(subject)) {
            return false;
        }
        // Document has no create permission. Use edit instead.
        if (subject instanceof Document) {
            return this.#getUserPermission(subject)?.edit ?? subject.permissions.edit;
        }
        return this.#getUserPermission(subject)?.create ?? subject.permissions.create;
    }
    canDelete(subject) {
        if (!this.canView(subject)) {
            return false;
        }
        // Documents can't be deleted
        if (subject instanceof Document) {
            return false;
        }
        return this.#getUserPermission(subject)?.delete ?? subject.permissions.delete;
    }
    canEdit(subject) {
        if (!this.canView(subject)) {
            return false;
        }
        return this.#getUserPermission(subject)?.edit ?? subject.permissions.edit;
    }
    canRename(subject) {
        if (!this.canView(subject)) {
            return false;
        }
        // Documents can't be renamed
        if (subject instanceof Document) {
            return false;
        }
        // Collections have the "auto" feature so we need to check rename === true
        return this.#getUserPermission(subject)?.rename ?? subject.permissions.rename === true;
    }
    #getUserPermission(subject) {
        for (const [name, permissions] of Object.entries(this.permissions)) {
            if (name === subject.name) {
                return permissions;
            }
        }
    }
}
